-- Frozen initial PostgreSQL schema. Apply ONLY with explicitly approved Alembic migration.
-- This migration has not been executed. These additive constraints are part of revision 0001.
CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email varchar(254) NOT NULL UNIQUE, display_name varchar(80) NOT NULL, password_hash text NOT NULL, is_active boolean NOT NULL DEFAULT true, is_admin boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE auth_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash varchar(64) NOT NULL UNIQUE, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE movies (id bigint PRIMARY KEY CHECK(id>0), title varchar(300) NOT NULL, overview text NOT NULL DEFAULT '', release_date varchar(10), runtime_minutes integer CHECK(runtime_minutes>0), original_language varchar(20), poster_path text, backdrop_path text, genres jsonb NOT NULL DEFAULT '[]', keywords jsonb NOT NULL DEFAULT '[]', features jsonb NOT NULL DEFAULT '{}', metadata_source varchar(80) NOT NULL, canonical_mapping_approved boolean NOT NULL DEFAULT false, content_version integer NOT NULL DEFAULT 1 CHECK(content_version>0), evidence_version integer NOT NULL DEFAULT 0 CHECK(evidence_version>=0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE external_movie_ids (movie_id bigint REFERENCES movies(id) ON DELETE CASCADE, source varchar(40), external_id varchar(120) NOT NULL, PRIMARY KEY(movie_id,source), UNIQUE(source,external_id));
CREATE TABLE reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, movie_id bigint NOT NULL REFERENCES movies(id), revision integer NOT NULL DEFAULT 1 CHECK(revision>0), text text NOT NULL, text_sha256 varchar(64) NOT NULL, language_code varchar(16) NOT NULL, user_rating numeric(2,1) CHECK(user_rating>=0.5 AND user_rating<=5 AND mod(user_rating*2,1)=0), training_permitted boolean NOT NULL DEFAULT false, evidence_permitted boolean NOT NULL DEFAULT false, consent_version varchar(80) NOT NULL, moderation_status varchar(20) NOT NULL DEFAULT 'published', analysis_status varchar(24) NOT NULL DEFAULT 'pending' CHECK(analysis_status IN ('pending','running','complete','partial','unavailable','failed','unsupported','cancelled')), is_deleted boolean NOT NULL DEFAULT false, is_synthetic boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE review_revisions (review_id uuid REFERENCES reviews(id) ON DELETE CASCADE, revision integer CHECK(revision>0), text text NOT NULL, text_sha256 varchar(64) NOT NULL, language_code varchar(16) NOT NULL, training_permitted boolean NOT NULL, evidence_permitted boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(review_id,revision));
CREATE TABLE predictions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), review_id uuid NOT NULL REFERENCES reviews(id) ON DELETE CASCADE, review_revision integer NOT NULL CHECK(review_revision>0), component varchar(40) NOT NULL, model_version varchar(128) NOT NULL, status varchar(30) NOT NULL, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(review_id,review_revision,component,model_version));
CREATE TABLE model_artifacts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), component varchar(40) NOT NULL, version varchar(128) NOT NULL, config_path text NOT NULL, run_path text NOT NULL, manifest_sha256 varchar(64) NOT NULL, approved boolean NOT NULL DEFAULT false, language_scope jsonb NOT NULL DEFAULT '[]', approval_reference text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(component,version));
CREATE TABLE jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind varchar(40) NOT NULL, dedupe_key varchar(220) NOT NULL UNIQUE, payload jsonb NOT NULL DEFAULT '{}', status varchar(20) NOT NULL DEFAULT 'queued' CHECK(status IN ('queued','running','succeeded','failed','unavailable','cancelled')), attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), available_at timestamptz NOT NULL DEFAULT now(), locked_at timestamptz, locked_by varchar(80), last_error varchar(80), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(status!='running' OR (locked_at IS NOT NULL AND locked_by IS NOT NULL)));
CREATE TABLE movie_scores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), movie_id bigint NOT NULL REFERENCES movies(id) ON DELETE CASCADE, score_type varchar(20) NOT NULL, target_key varchar(80), evidence_version integer NOT NULL, score numeric(6,3) CHECK(score>=0 AND score<=100), payload jsonb NOT NULL DEFAULT '{}', model_version varchar(128) NOT NULL, method_version varchar(128) NOT NULL, is_stale boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE movie_summaries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), movie_id bigint NOT NULL REFERENCES movies(id) ON DELETE CASCADE, evidence_version integer NOT NULL, payload jsonb NOT NULL DEFAULT '{}', is_stale boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE movie_embeddings (movie_id bigint REFERENCES movies(id) ON DELETE CASCADE, model_version varchar(128), content_version integer NOT NULL, dimension integer NOT NULL CHECK(dimension>0 AND dimension<=4096), embedding vector NOT NULL, PRIMARY KEY(movie_id,model_version), CHECK(vector_dims(embedding)=dimension));
CREATE TABLE review_embeddings (review_id uuid REFERENCES reviews(id) ON DELETE CASCADE, model_version varchar(128), review_revision integer NOT NULL, dimension integer NOT NULL CHECK(dimension>0 AND dimension<=4096), embedding vector NOT NULL, PRIMARY KEY(review_id,model_version), CHECK(vector_dims(embedding)=dimension));
CREATE TABLE ratings (user_id uuid REFERENCES users(id) ON DELETE CASCADE, movie_id bigint REFERENCES movies(id) ON DELETE CASCADE, value numeric(2,1) NOT NULL CHECK(value>=0.5 AND value<=5 AND mod(value*2,1)=0), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,movie_id));
CREATE TABLE watchlists (user_id uuid REFERENCES users(id) ON DELETE CASCADE, movie_id bigint REFERENCES movies(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,movie_id));
CREATE TABLE preferences (user_id uuid PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, genres jsonb NOT NULL DEFAULT '{}', themes jsonb NOT NULL DEFAULT '{}', personalization_permitted boolean NOT NULL DEFAULT false, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE interactions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, movie_id bigint NOT NULL REFERENCES movies(id) ON DELETE CASCADE, event_type varchar(30) NOT NULL, payload jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency (user_id uuid REFERENCES users(id) ON DELETE CASCADE, scope varchar(80), key_hash varchar(64), payload_hash varchar(64) NOT NULL, response jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,scope,key_hash));
CREATE TABLE conversations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, state jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE chat_turns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), conversation_id uuid NOT NULL REFERENCES conversations(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, query text NOT NULL, reply jsonb NOT NULL DEFAULT '{}', status varchar(20) NOT NULL DEFAULT 'pending', created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX reviews_movie_created ON reviews(movie_id,created_at DESC);
CREATE INDEX reviews_user ON reviews(user_id);
CREATE INDEX predictions_review ON predictions(review_id);
CREATE INDEX jobs_ready ON jobs(status,available_at);
CREATE INDEX movies_title ON movies(lower(title));
CREATE INDEX interactions_user_time ON interactions(user_id,created_at DESC);
ALTER TABLE reviews ADD COLUMN moderation_permitted boolean NOT NULL DEFAULT false;
ALTER TABLE model_artifacts ADD CONSTRAINT model_artifacts_version_unique UNIQUE(version);

